pub(crate) fn sv_eliminate(held: &mut Vec<SvHeld>, solved: &mut Vec<SvSolved>, book: &mut SvBook) -> SvChecked {
    if !book.reals.is_empty() { return SvChecked::Unknown(LgUnknown::OutsideTheTheory); }
    let mut skipped: Vec<SvRow> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut extended = false;
    let mut rounds = 0;
    while rounds < 4096 {
        rounds += 1;
        let mut kept: Vec<SvHeld> = vec![];
        for h in held.iter() {
            let t = match sv_tidy(&h.clone(), book) { Some(__nikaia_value) => __nikaia_value, None => return SvChecked::Unknown(LgUnknown::Overflow) };
            if !t.row.cols.is_empty() {
                kept.push(t);
                continue;
            }
            if t.row.constant > 0 {
                let clause = match book.farkas(vec![t.src], vec![1]) { Some(__nikaia_value) => __nikaia_value, None => return SvChecked::Unknown(LgUnknown::Overflow) };
                return SvChecked::Conflict(clause);
            }
        }
        *held = kept;
        let mut lo: i64 = -1;
        let mut hi: i64 = -1;
        let mut best: i64 = 0;
        let mut i: i64 = 0;
        while ((i) as usize) < held.len() {
            let mut j: i64 = unsafe { nikaia_std::proven::add::<i64>(i, 1) };
            while j < held.len() as i64 {
                if sv_opposite(&unsafe { nikaia_std::proven::read(&held, (i) as usize) }.row, &unsafe { nikaia_std::proven::read(&held, (j) as usize) }.row) {
                    let sum = match unsafe { nikaia_std::proven::read(&held, (i) as usize) }.row.constant.checked_add(unsafe { nikaia_std::proven::read(&held, (j) as usize) }.row.constant) { Some(__nikaia_value) => __nikaia_value, None => return SvChecked::Unknown(LgUnknown::Overflow) };
                    if sum > 0 {
                        let clause = match book.farkas(vec![unsafe { nikaia_std::proven::read(&held, (i) as usize) }.src.clone(), unsafe { nikaia_std::proven::read(&held, (j) as usize) }.src.clone()], vec![1, 1]) { Some(__nikaia_value) => __nikaia_value, None => return SvChecked::Unknown(LgUnknown::Overflow) };
                        return SvChecked::Conflict(clause);
                    }
                    let mut known = false;
                    for s in skipped.iter() { known = known || sv_row_same(s, &unsafe { nikaia_std::proven::read(&held, (i) as usize) }.row); }
                    if sum == 0 && !known {
                        let unit = sv_unit_column(&unsafe { nikaia_std::proven::read(&held, (i) as usize) }.row, &held).is_some();
                        let cost = unsafe { nikaia_std::proven::read(&held, (i) as usize) }.row.cols.len() as i64 + if unit { 0 } else { 4294967296i64 };
                        if lo < 0 || cost < best {
                            lo = i;
                            hi = j;
                            best = cost;
                        }
                    }
                }
                j = unsafe { nikaia_std::proven::add::<i64>(j, 1) };
            }
            i = unsafe { nikaia_std::proven::add::<i64>(i, 1) };
        }
        if lo < 0 {
            if extended && sv_reduce_step(held, solved, book) { continue; }
            break;
        }
        let column = sv_unit_column(&nikaia_std::index::get(&held, nikaia_std::index::at(lo)).row, &held);
        if column.is_none() {
            let at = held.len() as i64;
            let eq = unsafe { nikaia_std::proven::read(&held, (lo) as usize) }.row.clone();
            match sv_extended(held, lo, hi, book) {
                None => { skipped.push(eq); },
                Some(xk) => {
                    extended = true;
                    let x = xk;
                    let s_row = nikaia_std::index::get(&held, nikaia_std::index::at(at)).row.clone();
                    let unit = sv_row_coef(&s_row, x);
                    let next = sv_substituted(&held, at, unsafe { nikaia_std::proven::add::<i64>(at, 1) }, x, unit, book);
                    if next.is_none() {
                        skipped.push(eq);
                        continue;
                    }
                    *held = match next { Some(__nikaia_value) => __nikaia_value, None => break };
                    solved.push(SvSolved { column: x, row: s_row });
                },
            }
            continue;
        }
        let x = match column { Some(__nikaia_value) => __nikaia_value, None => break };
        let s = sv_row_coef(&unsafe { nikaia_std::proven::read(&held, (lo) as usize) }.row, x);
        let row = unsafe { nikaia_std::proven::read(&held, (lo) as usize) }.row.clone();
        let next = sv_substituted(&held, lo, hi, x, s, book);
        if next.is_none() {
            skipped.push(row);
            continue;
        }
        *held = match next { Some(__nikaia_value) => __nikaia_value, None => break };
        solved.push(SvSolved { column: x, row });
    }
    SvChecked::Consistent
}

#[cfg(test)]
pub(crate) fn sv_elim_test_answer_kind(answer: &LgAnswer) -> String {
    match answer {
        LgAnswer::Proved { .. } => String::from("proved"),
        LgAnswer::Refuted { .. } => String::from("refuted"),
        LgAnswer::Unknown { why } => sv_unknown(why),
    }
}

#[cfg(test)]
pub(crate) fn sv_elim_test_engine(arena: &TermArena, facts: &[i64], goal: i64, theory: String) -> String {
    let run = sv_smt_engine(arena, facts, goal, &lg_budget(), theory);
    match run.driven {
        SvDriven::Proved(ref query, ref steps) => {
            let v = sv_check(query, steps);
            if v.ok { format!("proved, log of {} steps checked", steps.len() as i64) } else { format!("log rejected: {}", v.reason) }
        },
        SvDriven::Answer(ref answer) => sv_elim_test_answer_kind(answer),
        SvDriven::RealModel(_) => String::from("refuted"),
    }
}

#[cfg(test)]
pub(crate) fn sv_elim_test_both(name: &str, source: &str) -> String {
    let script = match lg_smtlib_read(source) {
        LgRead::Script(ref s) => s.clone(),
        LgRead::Failed(_) => { return format!("{}: unreadable\n", name); },
    };
    let mut arena = script.arena.clone();
    let goal = arena.boolean(false);
    let simplex = sv_elim_test_engine(&arena, &script.assertions, goal, String::from("simplex"));
    let fm = sv_elim_test_engine(&arena, &script.assertions, goal, String::from("fm"));
    let both = sv_elim_test_engine(&arena, &script.assertions, goal, String::from("both"));
    format!("{}: simplex {}; fm {}; both {}\n", name, simplex, fm, both)
}

